def gen(rng):
    ALPHA = 'abcdefghijklmnopqrstuvwxyz'

    def fmt(ops):
        return str(len(ops)) + '\n' + '\n'.join(ops)

    def rw(alpha, lo, hi):
        return ''.join(rng.choice(alpha) for _ in range(rng.randint(lo, hi)))

    def rand_ops(q, alpha, lo, hi, w_ins=0.4):
        ops, ins = [], []
        for _ in range(q):
            r = rng.random()
            if r < w_ins or not ins:
                x = rw(alpha, lo, hi)
                ins.append(x)
                ops.append('insert ' + x)
            else:
                base = rng.choice(ins)
                kind = rng.random()
                if kind < 0.3:
                    ops.append('search ' + base)
                elif kind < 0.55:
                    ops.append('search ' + base[:rng.randint(1, len(base))])
                elif kind < 0.85:
                    ops.append('startsWith ' + base[:rng.randint(1, len(base))])
                elif kind < 0.93:
                    ops.append('startsWith ' + base + rng.choice(alpha))
                else:
                    ops.append(rng.choice(['search ', 'startsWith ']) + rw(alpha, lo, hi))
        return ops

    tests = [fmt(['insert car', 'search car', 'search ca', 'startsWith ca', 'insert ca', 'search ca', 'startsWith cat']),
             fmt(['insert zoe', 'insert zoo', 'startsWith zo', 'startsWith z', 'search zo', 'startsWith zoom']),
             fmt(['search a']), fmt(['startsWith a']), fmt(['insert a', 'search a', 'startsWith a', 'search aa', 'startsWith aa']),
             fmt(['insert abc', 'insert abc', 'search abc', 'search ab', 'startsWith abc', 'startsWith abcd']),
             fmt(['insert abcd', 'insert abc', 'insert ab', 'search a', 'search ab', 'search abc', 'search abcd', 'startsWith a'])]
    for _ in range(18):
        alpha = rng.choice(['a', 'ab', 'abc', ALPHA])
        tests.append(fmt(rand_ops(rng.randint(2, 30), alpha, 1, 6)))
    # max sized
    tests.append(fmt(rand_ops(40000, 'abc', 1, 10)))
    tests.append(fmt(rand_ops(40000, ALPHA, 3, 8, 0.5)))
    tests.append(fmt(rand_ops(40000, 'ab', 1, 14, 0.3)))
    # long words
    words = [rw('ab', 2000, 2000) for _ in range(60)]
    ops = ['insert ' + w for w in words]
    for _ in range(100):
        w = rng.choice(words)
        ops.append(rng.choice(['search ', 'startsWith ']) + w[:rng.randint(1, 2000)])
    tests.append(fmt(ops))
    base = rw(ALPHA, 2000, 2000)
    ops = ['insert ' + base[:i] for i in range(1, 2001, 31)]
    for i in range(1, 2001, 41):
        ops.append('search ' + base[:i])
        ops.append('startsWith ' + base[:i] + 'z')
    tests.append(fmt(ops))
    return tests
